export type DrawingTool = 'pen' | 'highlighter' | 'eraser';
export type BoardPosition = 'left' | 'right' | 'full';
export interface Point {
    x: number;
    y: number;
    pressure?: number;
}
export interface Stroke {
    id?: string;
    points: Point[];
    color: string;
    width: number;
    opacity: number;
    tool: DrawingTool;
    lineCap: string;
}
export interface DrawingData {
    version: number;
    width: number;
    height: number;
    strokes: Stroke[];
}
